{"content":"import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useState, type FormEvent } from "react";
import { toast } from "sonner";
import { supabase } from "@/integrations/supabase/client";

export const Route = createFileRoute("/reset-password")({
  head: () => ({
    meta: [
      { title: "Reset Password | Pickrel Brothers Inc." },
      {
        name: "description",
        content: "Set a new password for your Pickrel Brothers account or staff pricing console login.",
      },
      { property: "og:title", content: "Reset Password | Pickrel Brothers Inc." },
      {
        property: "og:description",
        content: "Set a new password for your Pickrel Brothers account.",
      },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary" },
      { name: "robots", content: "noindex" },
    ],
  }),
  component: ResetPasswordPage,
});

function ResetPasswordPage() {
  const navigate = useNavigate();
  const [password, setPassword] = useState("");
  const [busy, setBusy] = useState(false);

  async function onSubmit(e: FormEvent) {
    e.preventDefault();
    setBusy(true);
    try {
      const { error } = await supabase.auth.updateUser({ password });
      if (error) throw error;
      toast.success("Password updated");
      void navigate({ to: "/account" });
    } catch (error) {
      toast.error(error instanceof Error ? error.message : "Could not update password");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="container-page py-16">
      <div className="mx-auto max-w-md rounded-md border border-border bg-card p-8 shadow-card">
        <h1 className="font-display text-3xl font-bold uppercase text-navy">Set a new password</h1>
        <p className="mt-2 text-sm text-muted-foreground">
          Open this page from the reset link in your email, then choose a new password.
        </p>
        <form onSubmit={onSubmit} className="mt-6 space-y-4">
          <label className="block text-sm font-semibold text-navy">
            New password
            <input
              type="password"
              required
              minLength={6}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="mt-1 block w-full rounded-md border border-input bg-card px-3 py-2 text-sm text-foreground"
            />
          </label>
          <button
            type="submit"
            disabled={busy}
            className="w-full rounded-md bg-navy px-6 py-3 font-display font-bold uppercase tracking-wide text-navy-foreground hover:bg-navy-muted disabled:opacity-60"
          >
            Update password
          </button>
        </form>
      </div>
    </div>
  );
}
